-- Reviewed P99 exchanges using existing quest primitives. Quest faction gating remains intentionally bypassed.
-- P99 contradicts itself about Air versus Water. Retain the upstream Air wand, which agrees with the P99 reward list. The two previously unknown wing IDs are resolved by item identity; XP/faction magnitudes use the source stub.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Hey there scrawny! I lead the finest team of laborers in all of Kael Drakkel! We've got little use for a weak creature like yourself, but if you want to help us out I've got a task for you.")
  elseif e.message:findi("task") then
    e.self:Say("Those pansy dragon would bees in the Tunarean Court have become quite the nuisance lately. The deaths of Lord Gossimerwind and Lord Prismwing would certainly put an end to the nuisance for a time. Bring me their wings as proof of their deaths.")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 24870, item2 = 24871 }) then
    e.self:Say("You've done well. Maybe that foolish court will learn yet that the expansion of Kael can not be impeded.")
    e.other:SummonItem(24887)
    e.other:AddEXP(25000)
    e.other:Faction(448, 10, 0)
    e.other:Faction(419, 10, 0)
    e.other:Faction(429, 10, 0)
    e.other:Faction(430, -10, 0)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
